// ===== v1.1.194 (PM-3, PM-4) — Biaya operasional Pamsimas, biaya per m³, dana pemeliharaan =====
// Biaya dicatat sebagai transaksi pengeluaran biasa (jurnal tetap sah) pada unit Pamsimas; dana pemeliharaan hanya saran di laporan (belum dijurnal)
const BIAYA_J=[["5200","Listrik pompa"],["5410","Bahan kimia (kaporit)"],["5420","Perawatan jaringan pipa"],["5430","Honor operator"],["5300","BBM"],["5400","Biaya lain"]],
 airUnit=()=>airCfg().unit_id||(db.business_units.find(isAct)||{})._id,
 airRsv=()=>{const p=+((db.settings.air_rsv||{}).pct);return p>=0&&p<=100?p:0},
 biayaNm=c=>(BIAYA_J.find(j=>"ACC"+j[0]===c)||[0,""])[1];
function biayaData(){const au=airUnit(),ac=new Set(BIAYA_J.map(j=>"ACC"+j[0])),M={},J={};let Bt=0,Q=0,R=0;
 const mo=m=>M[m]??={m,b:0,q:0,r:0};
 db.journal_lines.forEach(l=>{if(!ac.has(l.account_id)||l.business_unit_id!==au||!inD(l.date))return;const v=l.debit-l.credit;mo(l.date.slice(0,7)).b+=v;J[l.account_id]=(J[l.account_id]||0)+v;Bt+=v});
 db.sales.forEach(x=>{if(!x.bill||x.status!=="posted"||x.unit_id!==au||!inD(x.date))return;const o=mo(x.date.slice(0,7));o.q+=x.bill.usage;o.r+=x.total;Q+=x.bill.usage;R+=x.total});
 const rows=Object.values(M).sort((a,b)=>b.m.localeCompare(a.m)),pct=airRsv();
 return{rows,J,Bt,Q,R,pct,rsv:Math.round(R*pct/100),bpm:Q>0?Bt/Q:null,tpm:Q>0?R/Q:null}}
