function pelCsvRows(t){t=String(t||"").replace(/^﻿/,"");const ls=t.split(/\r?\n/).filter(l=>l.trim());if(!ls.length)return[];const d=(ls[0].match(/;/g)||[]).length>(ls[0].match(/,/g)||[]).length?";":",";
 const sp=l=>{const o=[];let c="",q=false;for(let i=0;i<l.length;i++){const h=l[i];if(q){if(h==='"'){if(l[i+1]==='"'){c+='"';i++}else q=false}else c+=h}else if(h==='"')q=true;else if(h===d){o.push(c.trim());c=""}else c+=h}o.push(c.trim());return o},R=ls.map(sp);
 if(/^(nama|name|pelanggan)$/i.test(R[0][0]))R.shift();return R.map(r=>({name:r[0]||"",phone:r[1]||"",address:r[2]||""}))}
function pelImpor(inp){if(noPerm("air.kelola"))return;const f=inp.files&&inp.files[0];if(!f)return;inp.value="";f.text().then(t=>{try{const R=pelCsvRows(t);if(!R.length)throw Error("berkas kosong");const seen=new Set(),baru=[];let dup=0,bad=0;R.forEach(r=>{if(!r.name.trim()){bad++;return}const k=[r.name,r.phone,r.address].join("|").toLowerCase();if(seen.has(k)||dupP("pelanggan",r.name.trim(),r.phone.trim(),r.address.trim(),null)){dup++;return}seen.add(k);baru.push({name:r.name.trim(),phone:r.phone.trim(),address:r.address.trim()})});
  if(!baru.length)throw Error("tidak ada pelanggan baru ("+dup+" sudah ada"+(bad?", "+bad+" tanpa nama":"")+")");S.pimp={baru,dup,bad,fn:f.name};askC("pelImp","")}catch(e){S.pimp=null;S.msg="⚠ Impor gagal: "+e.message;render()}})}
function pelImpGo(){const P=S.pimp;if(!P||noPerm("air.kelola"))return;P.baru.forEach(f=>db.parties.push({_id:uid("PTY"),type:"pelanggan",...f,status:"aktif"}));audit("create","party","",P.baru.length+" pelanggan dari CSV "+P.fn);save();S.msg=P.baru.length+" pelanggan diimpor"+(P.dup?" · "+P.dup+" dilewati (sudah ada)":"");S.pimp=null;render()}

// v1.1.291 (PM7): janji bayar pada tagihan/piutang Pamsimas
function janjiSave(id){try{if(noPerm("air.kelola"))return;const x=db.sales.find(q=>q._id===id);if(!x||owedS(x)<=0.005)throw Error("piutang tidak ditemukan atau sudah lunas");const d=($("#wj-d")||{}).value||"",n=(($("#wj-n")||{}).value||"").trim();
 if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||isNaN(Date.parse(d)))throw fe("wj-d","Tanggal janji tidak valid");if(d<today())throw fe("wj-d","Tanggal janji tidak boleh sebelum hari ini");
 x.janji={d,n,by:(curUser()||{}).name||""};audit("update","sale",id,"janji bayar "+d+(n?" · "+n:""));save();S.msg="Janji bayar disimpan";S.fe=null}catch(e){S.msg="⚠ "+e.message;S.fe=e.f?{id:e.f,m:e.message}:null}render()}
function janjiDel(id){if(noPerm("air.kelola"))return;const x=db.sales.find(q=>q._id===id);if(!x||!x.janji)return;delete x.janji;audit("update","sale",id,"janji bayar dihapus");save();S.msg="Janji bayar dihapus";render()}
